def load() -> pd.DataFrame:
    import pandas as pd, glob
    files = sorted(glob.glob('data/environment/input/*_beach_datasheet.csv'))
    out = []
    for f in files:
        df = pd.read_csv(f, header=None, dtype=str)
        df['file'] = f
        df['row'] = range(len(df))
        out.append(df)
    return pd.concat(out, ignore_index=True)
